const ROUND = /^##\s+Round\s+(\d+)\b(.*)$/
const SUBMITTED = /submitted\s+(\S+)/i
const COMMENT = /^-\s+(C\d+)\s*\(([^)]*)\)\s*:\s*(.*)$/
const STRUCK = /^-\s+struck\s*:\s*(.*)$/i
const CHILD = /^\s+-\s+(.*)$/
const RESOLUTION = /^(?:resolution\s*)?\(?(addressed|disagreed)\)?\s*:\s*(.*)$/i
const ITEM_TEXT = /^item\s*:\s*(.*)$/i
const ACCEPTED = /^accepted\b/i

export function parseReview(text: string): Review {
  const review: Review = { rounds: [] }
  let round: ReviewRound | undefined
  let comment: ReviewComment | undefined
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trimEnd()
    const roundMatch = ROUND.exec(line.trim())
    if (roundMatch) {
      const submitted = SUBMITTED.exec(roundMatch[2] ?? '')
      round = {
        number: Number(roundMatch[1]),
        ...(submitted ? { submittedAt: submitted[1]! } : {}),
        comments: [],
        strikes: [],
      }
      comment = undefined
      review.rounds.push(round)
      continue
    }
    if (!round) continue
    const child = CHILD.exec(line)
    if (child && comment) {
      const body = child[1]!.trim()
      const resolution = RESOLUTION.exec(body)
      if (resolution) {
        comment.resolution = { kind: resolution[1]!.toLowerCase() as ResolutionKind, text: resolution[2]!.trim() }
        continue
      }
      const item = ITEM_TEXT.exec(body)
      if (item) {
        comment.item = item[1]!.trim()
        continue
      }
      if (ACCEPTED.test(body)) comment.closed = true
      continue
    }
    const trimmed = line.trim()
    const struck = STRUCK.exec(trimmed)
    if (struck) {
      round.strikes = struck[1]!
        .split(',')
        .map((s) => s.trim())
        .filter((s) => s.length > 0)
      comment = undefined
      continue
    }
    const commentMatch = COMMENT.exec(trimmed)
    if (commentMatch) {
      comment = { id: commentMatch[1]!, target: commentMatch[2]!.trim(), text: commentMatch[3]!.trim() }
      round.comments.push(comment)
      continue
    }
    if (trimmed.length > 0) comment = undefined
  }
  return review
}

export function renderReview(review: Review, title: string): string {
  const lines = [
    `# Review of ${title}`,
    '',
    'Comments and strikes are the human\u2019s; resolutions are the agent\u2019s. Ids are stable and never reused.',
  ]
  for (const round of review.rounds) {
    lines.push('', `## Round ${round.number}${round.submittedAt ? ` — submitted ${round.submittedAt}` : ' — pending'}`)
    for (const comment of round.comments) {
      lines.push(`- ${comment.id} (${comment.target}): ${comment.text}`)
      if (comment.item) lines.push(`  - item: ${comment.item}`)
      if (comment.resolution) lines.push(`  - ${comment.resolution.kind}: ${comment.resolution.text}`)
      if (comment.closed) lines.push('  - accepted')
    }
    if (round.strikes.length > 0) lines.push(`- struck: ${round.strikes.join(', ')}`)
  }
  return lines.join('\n') + '\n'
}

export async function readReview(path: string): Promise<Review> {
  try {
    return parseReview(await readFile(path, 'utf8'))
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return emptyReview()
    throw error
  }
}

export async function writeReview(path: string, review: Review, title: string): Promise<void> {
  await writeFile(path, renderReview(review, title), 'utf8')
}

// --- authoring ---------------------------------------------------------------

/** The round being written, if any; a submitted review has none until the human comments again. */
export function pendingRound(review: Review): ReviewRound | undefined {
  const last = review.rounds.at(-1)
  return last && last.submittedAt === undefined ? last : undefined
}

function openRound(review: Review): ReviewRound {
  const existing = pendingRound(review)
  if (existing) return existing
  const round: ReviewRound = { number: (review.rounds.at(-1)?.number ?? 0) + 1, comments: [], strikes: [] }
  review.rounds.push(round)
  return round
}

function allComments(review: Review): ReviewComment[] {
  return review.rounds.flatMap((r) => r.comments)
}

/** Ids are never reused, so the next one counts past every id ever given out. */
function nextCommentId(review: Review): string {
  const highest = allComments(review).reduce((max, c) => Math.max(max, Number(c.id.slice(1)) || 0), 0)
  return `C${highest + 1}`
}

/** Comments are one line in the file; a pasted paragraph keeps its words, not its line breaks. */
const oneLine = (text: string): string => text.replace(/\s+/g, ' ').trim()

export function addComment(review: Review, target: string, text: string, itemText?: string): ReviewComment {
  const body = oneLine(text)
  if (!body) throw new Error('A comment needs text.')
  const comment: ReviewComment = {
    id: nextCommentId(review),
    target,
    text: body,
    ...(itemText ? { item: oneLine(itemText) } : {}),
  }
  openRound(review).comments.push(comment)
  return comment
}

function requirePending(review: Review, id: string): { round: ReviewRound; index: number } {
  const round = pendingRound(review)
  const index = round?.comments.findIndex((c) => c.id === id) ?? -1
  if (!round || index === -1) throw new Error(`Comment ${id} is submitted and cannot be changed.`)
  return { round, index }
}

export function editComment(review: Review, id: string, text: string): void {
  const body = oneLine(text)
  if (!body) throw new Error('A comment needs text.')
  const { round, index } = requirePending(review, id)
  round.comments[index]!.text = body
}

export function removeComment(review: Review, id: string): void {
  const { round, index } = requirePending(review, id)
  round.comments.splice(index, 1)
  prune(review)
}

/** A round with nothing in it is not a round; it appears again on the next comment. */
function prune(review: Review): void {
  const round = pendingRound(review)
  if (round && round.comments.length === 0 && round.strikes.length === 0) review.rounds.pop()
}

export function strikeItem(review: Review, itemId: string): void {
  if (struckItems(review).includes(itemId)) return
  openRound(review).strikes.push(itemId)
}

/** Only an unsubmitted strike can be taken back; a struck item stays removed (B2, B9). */
export function unstrikeItem(review: Review, itemId: string): void {
  const round = pendingRound(review)
  if (!round?.strikes.includes(itemId)) throw new Error(`${itemId} is already struck in a submitted round.`)
  round.strikes = round.strikes.filter((s) => s !== itemId)
  prune(review)
}

/** Every item ever struck, submitted or not. */
export function struckItems(review: Review): string[] {
  return [...new Set(review.rounds.flatMap((r) => r.strikes))]
}

export function commentsFor(review: Review, target: string): ReviewComment[] {
  return allComments(review).filter((c) => c.target === target)
}

/** A review with nothing in it is refused rather than sent; no turn is spent on it (E2). */
export function submitRound(review: Review, at: string = new Date().toISOString()): ReviewRound {
  const round = pendingRound(review)
  if (!round || (round.comments.length === 0 && round.strikes.length === 0)) {
    throw new Error('The review is empty: comment on something or strike an item first.')
  }
  round.submittedAt = at
  return round
}

/** Accepting is an explicit act, including when the agent disagreed (B8). */
export function acceptResolution(review: Review, commentId: string): void {
  const comment = allComments(review).find((c) => c.id === commentId)
  if (!comment) throw new Error(`Unknown comment ${commentId}.`)
  if (!comment.resolution) throw new Error(`Comment ${commentId} has no resolution yet.`)
  comment.closed = true
}

/** Every comment the human has not closed, submitted or still being written. */
export function openComments(review: Review): ReviewComment[] {
  return allComments(review).filter((c) => !c.closed)
}

/** A plan cannot be approved while any comment is open (B10). */
export function assertApprovable(review: Review): void {
  const open = openComments(review)
  if (open.length === 0) return
  throw new Error(`The review is not closed: ${open.map((c) => c.id).join(', ')} still open.`)
}

import { describe, expect, it } from 'vitest'
import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import {
  acceptResolution,
  addComment,
  assertApprovable,
  assertCommentable,
  editComment,
  emptyReview,
  isCommentable,
  openComments,
  parseReview,
  pendingRound,
  planItems,
  readReview,
  removeComment,
  renderReview,
  reviewPath,
  strikeItem,
  struckItems,
  submitRound,
  unstrikeItem,
  writeReview,
} from '../src/agent/phases/plan-review'

const body = `# Orders

## Behaviour
- B1: an order can be cancelled
- B2: a cancelled order is refunded [removed]

## Tasks
- T1: cancellation (B1, B2)

## Findings
- F1 (contradiction, B1): the code says otherwise
`

describe('plan items', () => {
  it('items_are_addressed_by_id_and_a_removed_item_is_still_an_item', () => {
    expect(planItems(body)).toEqual([
      { id: 'B1', text: 'an order can be cancelled', section: 'Behaviour', removed: false },
      { id: 'B2', text: 'a cancelled order is refunded [removed]', section: 'Behaviour', removed: true },
      { id: 'T1', text: 'cancellation (B1, B2)', section: 'Tasks', removed: false },
      { id: 'F1', text: '(contradiction, B1) the code says otherwise', section: 'Findings', removed: true === false ? true : false },
    ])
  })
})

describe('review authoring', () => {
  it('a_comment_can_be_attached_to_an_item_and_to_the_plan_as_a_whole', () => {
    const review = emptyReview()
    addComment(review, 'B1', 'this is not what cancelling means', 'B1: an order can be cancelled')
    addComment(review, 'plan', 'the goal misses the refund story')
    expect(review.rounds).toHaveLength(1)
    expect(review.rounds[0]).toMatchObject({ number: 1, strikes: [] })
    expect(review.rounds[0]!.comments).toEqual([
      { id: 'C1', target: 'B1', text: 'this is not what cancelling means', item: 'B1: an order can be cancelled' },
      { id: 'C2', target: 'plan', text: 'the goal misses the refund story' },
    ])
  })

  it('a_pending_comment_can_be_edited_and_removed_a_submitted_one_cannot', () => {
    const review = emptyReview()
    addComment(review, 'B1', 'wrong')
    editComment(review, 'C1', 'still wrong, and here is why')
    expect(review.rounds[0]!.comments[0]!.text).toBe('still wrong, and here is why')
    removeComment(review, 'C1')
    expect(review.rounds).toHaveLength(0)

    addComment(review, 'B1', 'wrong again')
    submitRound(review, '2026-01-01T00:00:00.000Z')
    expect(() => editComment(review, 'C2', 'no')).toThrow(/submitted/)
    expect(() => removeComment(review, 'C2')).toThrow(/submitted/)
  })

  it('ids_are_never_reused_after_a_comment_is_removed', () => {
    const review = emptyReview()
    addComment(review, 'B1', 'one')
    addComment(review, 'B2', 'two')
    removeComment(review, 'C2')
    expect(addComment(review, 'B2', 'again').id).toBe('C3')
  })

  it('an_item_can_be_struck_and_unstruck_while_the_review_is_unsubmitted', () => {
    const review = emptyReview()
    strikeItem(review, 'B2')
    strikeItem(review, 'B2')
    expect(struckItems(review)).toEqual(['B2'])
    unstrikeItem(review, 'B2')
    expect(struckItems(review)).toEqual([])
    expect(review.rounds).toHaveLength(0)
  })

  it('a_struck_item_cannot_be_unstruck_once_the_round_is_submitted', () => {
    const review = emptyReview()
    strikeItem(review, 'B2')
    submitRound(review, '2026-01-01T00:00:00.000Z')
    expect(() => unstrikeItem(review, 'B2')).toThrow(/submitted/)
    expect(struckItems(review)).toEqual(['B2'])
  })

  it('the_pending_review_is_one_batch_shown_as_a_whole_and_submitted_at_once', () => {
    const review = emptyReview()
    addComment(review, 'B1', 'one')
    strikeItem(review, 'B2')
    const pending = pendingRound(review)
    expect(pending?.comments.map((c) => c.id)).toEqual(['C1'])
    expect(pending?.strikes).toEqual(['B2'])
    submitRound(review, '2026-01-01T00:00:00.000Z')
    expect(pendingRound(review)).toBeUndefined()
    addComment(review, 'B1', 'next round')
    expect(pendingRound(review)?.number).toBe(2)
  })

  it('an_empty_review_is_refused_so_no_turn_is_spent', () => {
    expect(() => submitRound(emptyReview())).toThrow(/empty/)
    const review = emptyReview()
    addComment(review, 'B1', 'x')
    removeComment(review, 'C1')
    expect(() => submitRound(review)).toThrow(/empty/)
  })

  it('a_comment_on_a_removed_item_is_allowed_it_is_how_a_struck_item_comes_back', () => {
    const review = emptyReview()
    strikeItem(review, 'B2')
    submitRound(review, '2026-01-01T00:00:00.000Z')
    const comment = addComment(review, 'B2', 'bring this one back, I struck it by mistake')
    expect(comment.target).toBe('B2')
    expect(pendingRound(review)?.comments).toHaveLength(1)
  })
})

describe('resolutions and the approval gate', () => {
  it('a_comment_stays_open_until_its_resolution_is_accepted_even_a_disagreement', () => {
    const review = emptyReview()
    addComment(review, 'B1', 'wrong')
    submitRound(review, '2026-01-01T00:00:00.000Z')
    expect(openComments(review).map((c) => c.id)).toEqual(['C1'])
    expect(() => acceptResolution(review, 'C1')).toThrow(/no resolution/)

    review.rounds[0]!.comments[0]!.resolution = { kind: 'disagreed', text: 'intent says otherwise' }
    expect(openComments(review).map((c) => c.id)).toEqual(['C1'])
    expect(() => assertApprovable(review)).toThrow(/C1/)
    acceptResolution(review, 'C1')
    expect(openComments(review)).toEqual([])
    expect(() => assertApprovable(review)).not.toThrow()
  })

  it('an_unsubmitted_comment_blocks_approval_too', () => {
    const review = emptyReview()
    addComment(review, 'B1', 'wait')
    expect(() => assertApprovable(review)).toThrow(/C1/)
  })
})

describe('commenting is offered on a draft only', () => {
  it('a_missing_or_approved_plan_is_not_commentable', () => {
    expect(isCommentable({ exists: true, status: 'draft', body })).toBe(true)
    expect(isCommentable({ exists: true, status: 'approved', body })).toBe(false)
    expect(isCommentable({ exists: false })).toBe(false)
    expect(() => assertCommentable({ exists: true, status: 'approved', body })).toThrow(/approved/)
    expect(() => assertCommentable({ exists: false })).toThrow(/No plan/)
  })
})

describe('the review file', () => {
  it('round_trips_comments_strikes_resolutions_and_acceptance', () => {
    const review = emptyReview()
    addComment(review, 'B1', 'not what cancelling means', 'B1: an order can be cancelled')
    addComment(review, 'plan', 'the goal misses refunds')
    strikeItem(review, 'B2')
    submitRound(review, '2026-01-01T00:00:00.000Z')
    review.rounds[0]!.comments[0]!.resolution = { kind: 'addressed', text: 'rewrote B1' }
    review.rounds[0]!.comments[1]!.resolution = { kind: 'disagreed', text: 'refunds are another feature' }
    acceptResolution(review, 'C1')
    addComment(review, 'B2', 'bring it back')

    const text = renderReview(review, 'plan/orders.spec.md')
    expect(text).toContain('# Review of plan/orders.spec.md')
    expect(text).toContain('## Round 1 — submitted 2026-01-01T00:00:00.000Z')
    expect(text).toContain('- C1 (B1): not what cancelling means')
    expect(text).toContain('  - addressed: rewrote B1')
    expect(text).toContain('  - accepted')
    expect(text).toContain('- struck: B2')
    expect(text).toContain('## Round 2 — pending')
    expect(parseReview(text)).toEqual(review)
  })

  it('a_resolution_the_agent_wrote_loosely_is_still_read', () => {
    const text = `# Review of plan/orders.spec.md

## Round 1 — submitted 2026-01-01T00:00:00.000Z
- C1 (B1): wrong
  - resolution (addressed): rewrote it
- C2 (plan): thin
  - Disagreed: the plan is deliberately short
`
    const review = parseReview(text)
    expect(review.rounds[0]!.comments[0]!.resolution).toEqual({ kind: 'addressed', text: 'rewrote it' })
    expect(review.rounds[0]!.comments[1]!.resolution).toEqual({ kind: 'disagreed', text: 'the plan is deliberately short' })
  })

  it('survives_a_reload_through_the_file_next_to_the_spec', async () => {
    const dir = await mkdtemp(join(tmpdir(), 'review-'))
    try {
      const path = reviewPath(dir, 'Order cancellation')
      expect(path).toBe(join(dir, 'plan', 'order-cancellation.review.md'))
      expect(await readReview(path)).toEqual(emptyReview())

      const review = emptyReview()
      addComment(review, 'B1', 'wrong')
      strikeItem(review, 'B3')
      await import('node:fs/promises').then((fs) => fs.mkdir(join(dir, 'plan'), { recursive: true }))
      await writeReview(path, review, 'plan/order-cancellation.spec.md')
      expect(await readReview(path)).toEqual(review)

      submitRound(review, '2026-01-01T00:00:00.000Z')
      await writeReview(path, review, 'plan/order-cancellation.spec.md')
      const reloaded = await readReview(path)
      expect(pendingRound(reloaded)).toBeUndefined()
      expect(struckItems(reloaded)).toEqual(['B3'])
      expect(openComments(reloaded).map((c) => c.id)).toEqual(['C1'])
    } finally {
      await rm(dir, { recursive: true, force: true })
    }
  })
})

