import { PLAN_DIR, featureSlug } from './blind-plan'
import {
  PLAN_TARGET,
  findItem,
  readReview,
  reviewFile,
  reviewPath,
  struckItems,
  submitRound,
  writeReview,
  type ReviewComment,
  type ReviewRound,
} from './plan-review'
import { readSpecState } from './spec-file'
import { specPath } from './blind-plan'
import type { SessionMode } from '../session/session-manager'

/** The phases that own a plan artifact and can therefore revise it. */
export type PlanPhase = Extract<SessionMode, 'plan' | 'reconcile'>

export const planPhaseOf = (mode: SessionMode): PlanPhase => (mode === 'reconcile' ? 'reconcile' : 'plan')

/** How a submitted review reaches a session: the owning one, or a fresh one of the same phase. */
export interface ReviewCourier {
  isLive(sessionId: string): boolean
  send(sessionId: string, text: string): Promise<void>
  start(phase: PlanPhase, feature: string, prompt: string): Promise<void>
}

export type ReviewOwner = { sessionId: string; phase: PlanPhase }

/** A comment as the agent gets it: the item it names, or the text it was written against when that id is gone (E5). */
type CarriedComment = { comment: ReviewComment; itemText: string | undefined; orphaned: boolean }

function carry(round: ReviewRound, body: string): CarriedComment[] {
  return round.comments.map((comment) => {
    if (comment.target === PLAN_TARGET) return { comment, itemText: undefined, orphaned: false }
    const item = findItem(body, comment.target)
    return {
      comment,
      itemText: item ? item.text : comment.item,
      orphaned: item === undefined,
    }
  })
}

function commentLine({ comment, itemText, orphaned }: CarriedComment): string {
  if (comment.target === PLAN_TARGET) return `- ${comment.id}, on the plan as a whole: ${comment.text}`
  if (!orphaned) return `- ${comment.id}, on ${comment.target}: ${comment.text}`
  const was = itemText ? ` It was written against: "${itemText}".` : ''
  return `- ${comment.id}, on ${comment.target}, which is no longer in the plan:${was} ${comment.text}`
}

/**
 * The message a review is handed over as. It stands on its own: the session
 * reads the plan and the review from disk, so a fresh session of the same
 * phase can revise exactly as the session that wrote the plan would (B4).
 */
export function reviewPrompt(options: {
  feature: string
  round: ReviewRound
  body: string
  struck: string[]
}): string {
  const { feature, round, body, struck } = options
  const spec = `${PLAN_DIR}/${featureSlug(feature)}.spec.md`
  const review = reviewFile(feature)
  const comments = carry(round, body)
  const lines = [
    `The human reviewed the plan for "${feature}" and submitted round ${round.number} of comments.`,
    '',
    `Read the plan at \`${spec}\` and the review at \`${review}\` from disk before you change anything; everything you need is in those two files, not in this conversation.`,
    '',
  ]
  lines.push(
    round.strikes.length > 0
      ? `Struck in this round, to be removed: ${round.strikes.join(', ')}.`
      : 'Nothing was struck in this round.',
  )
  if (struck.length > round.strikes.length) {
    lines.push(`Struck in earlier rounds and still gone: ${struck.filter((s) => !round.strikes.includes(s)).join(', ')}.`)
  }
  lines.push('', comments.length > 0 ? 'Comments:' : 'No comments in this round.')
  for (const carried of comments) lines.push(commentLine(carried))
  lines.push(
    '',
    `In the plan, \`${spec}\`:`,
    '- Mark every struck item removed by appending ` [removed]` to its line. Do not delete the line and do not renumber anything: an id belongs to the item it was given to, for good.',
    '- Repair the items that referred to a removed item, so the plan still holds together without it.',
    '- Never reintroduce a struck item, in this round or a later one. Only a new comment from the human can bring one back.',
    '- If every item is now struck, change nothing further: report that nothing remains and stop. Do not invent a replacement plan.',
    '',
    `In the review, \`${review}\`:`,
    '- Answer every comment of this round. Under its line, indented two spaces, add exactly one of:',
    '  - `  - addressed: what you changed` when you did what it asks;',
    '  - `  - disagreed: why you will not` when you will not, with the reason stated.',
    '- Never leave a comment unanswered and never remove one. The comments, their ids and the struck list are the human\u2019s; touch nothing else in that file.',
    '',
    'Then, in chat: what changed in the plan since the review was submitted, and each comment with its resolution. Then stop; the human decides what happens next.',
  )
  return lines.join('\n')
}

/**
 * Submits the pending round: marks it submitted on disk and hands plan and
 * review to the session that owns the artifact, or to a fresh one of the same
 * phase when that session is gone (B4). An empty review is refused (E2).
 */
export async function submitReview(options: {
  courier: ReviewCourier
  cwd: string
  feature: string
  owner: ReviewOwner
  now?: string
}): Promise<ReviewRound> {
  const { courier, cwd, feature, owner } = options
  const spec = specPath(cwd, feature)
  const state = await readSpecState(spec)
  if (!state.exists) throw new Error('No plan to review yet.')
  if (state.status !== 'draft') throw new Error('An approved plan is not commentable: reopen or supersede it.')

  const path = reviewPath(cwd, feature)
  const review = await readReview(path)
  const round = submitRound(review, options.now ?? new Date().toISOString())
  await writeReview(path, review, `${PLAN_DIR}/${featureSlug(feature)}.spec.md`)

  const prompt = reviewPrompt({ feature, round, body: state.body, struck: struckItems(review) })
  if (courier.isLive(owner.sessionId)) await courier.send(owner.sessionId, prompt)
  else await courier.start(owner.phase, feature, prompt)
  return round
}

import { describe, expect, it } from 'vitest'
import { mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import {
  addComment,
  emptyReview,
  pendingRound,
  readReview,
  reviewPath,
  strikeItem,
  submitRound,
  writeReview,
  type Review,
} from '../src/agent/phases/plan-review'
import { planPhaseOf, reviewPrompt, submitReview, type PlanPhase, type ReviewCourier } from '../src/agent/phases/review-handoff'
import { specPath } from '../src/agent/phases/blind-plan'

const spec = `---
feature: Order cancellation
status: draft
---

# Order cancellation

## Behaviour
- B1: an order can be cancelled
- B2: a cancelled order is refunded

## Tasks
- T1: cancellation (B1, B2)
`

const body = spec.split('---\n')[2]!.replace(/^\s+/, '')

type Delivery = { kind: 'send'; sessionId: string; text: string } | { kind: 'start'; phase: PlanPhase; feature: string; text: string }

function courier(live: string[]): ReviewCourier & { delivered: Delivery[] } {
  const delivered: Delivery[] = []
  return {
    delivered,
    isLive: (id) => live.includes(id),
    send: async (sessionId, text) => void delivered.push({ kind: 'send', sessionId, text }),
    start: async (phase, feature, text) => void delivered.push({ kind: 'start', phase, feature, text }),
  }
}

async function workspace(review?: Review): Promise<string> {
  const dir = await mkdtemp(join(tmpdir(), 'handoff-'))
  await mkdir(join(dir, 'plan'), { recursive: true })
  await writeFile(specPath(dir, 'Order cancellation'), spec, 'utf8')
  if (review) await writeReview(reviewPath(dir, 'Order cancellation'), review, 'plan/order-cancellation.spec.md')
  return dir
}

function pending(): Review {
  const review = emptyReview()
  addComment(review, 'B1', 'cancelling is not the same as voiding', 'B1: an order can be cancelled')
  strikeItem(review, 'B2')
  return review
}

describe('submitting a review', () => {
  it('goes_to_the_owning_session_when_it_is_still_alive', async () => {
    const dir = await workspace(pending())
    try {
      const post = courier(['owner-1'])
      const round = await submitReview({
        courier: post,
        cwd: dir,
        feature: 'Order cancellation',
        owner: { sessionId: 'owner-1', phase: 'plan' },
        now: '2026-01-01T00:00:00.000Z',
      })
      expect(round.number).toBe(1)
      expect(post.delivered).toHaveLength(1)
      expect(post.delivered[0]).toMatchObject({ kind: 'send', sessionId: 'owner-1' })
      expect(post.delivered[0]!.text).toContain('C1, on B1: cancelling is not the same as voiding')

      const stored = await readReview(reviewPath(dir, 'Order cancellation'))
      expect(stored.rounds[0]!.submittedAt).toBe('2026-01-01T00:00:00.000Z')
      expect(pendingRound(stored)).toBeUndefined()
    } finally {
      await rm(dir, { recursive: true, force: true })
    }
  })

  it('goes_to_a_fresh_session_of_the_same_phase_when_the_owner_is_gone', async () => {
    const dir = await workspace(pending())
    try {
      const post = courier([])
      await submitReview({
        courier: post,
        cwd: dir,
        feature: 'Order cancellation',
        owner: { sessionId: 'owner-1', phase: 'reconcile' },
      })
      expect(post.delivered[0]).toMatchObject({ kind: 'start', phase: 'reconcile', feature: 'Order cancellation' })
      // The fresh session is told to read both files rather than a transcript it does not have.
      expect(post.delivered[0]!.text).toContain('plan/order-cancellation.spec.md')
      expect(post.delivered[0]!.text).toContain('plan/order-cancellation.review.md')
      expect(post.delivered[0]!.text).toContain('from disk')
    } finally {
      await rm(dir, { recursive: true, force: true })
    }
  })

  it('an_empty_review_is_refused_and_nothing_is_sent', async () => {
    const dir = await workspace()
    try {
      const post = courier(['owner-1'])
      await expect(
        submitReview({ courier: post, cwd: dir, feature: 'Order cancellation', owner: { sessionId: 'owner-1', phase: 'plan' } }),
      ).rejects.toThrow(/empty/)
      expect(post.delivered).toEqual([])
    } finally {
      await rm(dir, { recursive: true, force: true })
    }
  })

  it('a_comment_whose_item_is_gone_from_the_file_is_carried_with_the_text_it_was_written_against', async () => {
    const review = emptyReview()
    addComment(review, 'B9', 'this promises too much', 'B9: every order is refunded within a day')
    const dir = await workspace(review)
    try {
      const post = courier(['owner-1'])
      await submitReview({
        courier: post,
        cwd: dir,
        feature: 'Order cancellation',
        owner: { sessionId: 'owner-1', phase: 'plan' },
      })
      const text = post.delivered[0]!.text
      expect(text).toContain('C1, on B9, which is no longer in the plan')
      expect(text).toContain('"B9: every order is refunded within a day"')
      expect(text).toContain('this promises too much')
    } finally {
      await rm(dir, { recursive: true, force: true })
    }
  })

  it('an_approved_plan_cannot_be_reviewed', async () => {
    const dir = await mkdtemp(join(tmpdir(), 'handoff-'))
    try {
      await mkdir(join(dir, 'plan'), { recursive: true })
      await writeFile(specPath(dir, 'Order cancellation'), spec.replace('status: draft', 'status: approved'), 'utf8')
      await writeReview(reviewPath(dir, 'Order cancellation'), pending(), 'plan/order-cancellation.spec.md')
      const post = courier(['owner-1'])
      await expect(
        submitReview({ courier: post, cwd: dir, feature: 'Order cancellation', owner: { sessionId: 'owner-1', phase: 'plan' } }),
      ).rejects.toThrow(/approved/)
      expect(post.delivered).toEqual([])
    } finally {
      await rm(dir, { recursive: true, force: true })
    }
  })

  it('the_phase_of_a_session_is_the_phase_its_review_goes_back_to', () => {
    expect(planPhaseOf('plan')).toBe('plan')
    expect(planPhaseOf('reconcile')).toBe('reconcile')
  })
})

describe('the revision the agent is asked for', () => {
  const review = (() => {
    const r = pending()
    addComment(r, 'plan', 'the goal reads like a summary')
    submitRound(r, '2026-01-01T00:00:00.000Z')
    return r
  })()
  const prompt = reviewPrompt({ feature: 'Order cancellation', round: review.rounds[0]!, body, struck: ['B2'] })

  it('names_the_struck_items_and_forbids_renumbering_and_resurrection', () => {
    expect(prompt).toContain('Struck in this round, to be removed: B2.')
    expect(prompt).toContain('[removed]')
    expect(prompt).toContain('do not renumber')
    expect(prompt).toContain('Never reintroduce a struck item')
    expect(prompt).toContain('Repair the items that referred to a removed item')
  })

  it('asks_for_a_resolution_on_every_comment_addressed_or_disagreed_with_a_reason', () => {
    expect(prompt).toContain('Answer every comment of this round')
    expect(prompt).toContain('addressed: what you changed')
    expect(prompt).toContain('disagreed: why you will not')
    expect(prompt).toContain('Never leave a comment unanswered')
  })

  it('says_what_to_do_when_the_plan_is_emptied', () => {
    expect(prompt).toContain('If every item is now struck')
    expect(prompt).toContain('Do not invent a replacement plan')
  })

  it('asks_for_the_revised_plan_and_its_resolutions_to_be_presented_then_a_stop', () => {
    expect(prompt).toContain('what changed in the plan since the review was submitted')
    expect(prompt).toContain('each comment with its resolution')
    expect(prompt).toContain('Then stop')
  })

  it('carries_the_plan_level_comment_as_a_comment_on_the_whole', () => {
    expect(prompt).toContain('C2, on the plan as a whole: the goal reads like a summary')
  })
})

